name: PR Preview Deployment

on:
  pull_request:
    paths:
      - "website/**"
  workflow_dispatch:

jobs:
  build-and-deploy:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      deployments: write
      issues: write
      pull-requests: write
    steps:
      - name: Checkout Code
        uses: actions/checkout@v4

      - name: Setup .NET
        uses: actions/setup-dotnet@v4
        with:
          dotnet-version: '8.0.x'

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20.x'
          cache: 'npm'

      - name: Install dependencies
        run: |
          cd website
          npm install

      - name: Build Website
        run: |
          cd website
          npm run build

      - name: Upload Artifact
        uses: actions/upload-artifact@v4
        with:
          name: preview-site
          path: website/dist/
          retention-days: 30

      - name: Deploy to Cloudflare Pages
        if: ${{ secrets.CLOUDFLARE_API_TOKEN && secrets.CLOUDFLARE_ACCOUNT_ID }}
        uses: cloudflare/wrangler-action@v3
        with:
          apiToken: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          accountId: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          workingDirectory: website
          command: pages deploy dist --project-name=razorconsole-preview --branch=pr-${{ github.event.number }}

      - name: Post PR Comment
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const path = require('path');

            // Read the preview deployment guide
            const previewGuidePath = path.join(__dirname, '..', '..', '.github', 'PREVIEW_DEPLOYMENT.md');
            let previewGuideContent = '';
            try {
              previewGuideContent = fs.readFileSync(previewGuidePath, 'utf8');
            } catch (error) {
              console.log('Preview guide not found, skipping.');
            }

            const isCloudflareConfigured = !!process.env.CLOUDFLARE_API_TOKEN && !!process.env.CLOUDFLARE_ACCOUNT_ID;

            let commentBody = `## 🚀 Preview Deployment\n\n`;

            if (isCloudflareConfigured) {
              commentBody += `A preview deployment is available at: https://pr-${{ github.event.number }}--razorconsole-preview.pages.dev\n\n`;
            }

            commentBody += `### 📦 Artifact Preview\n\n`;
            commentBody += `You can download the built site as an artifact:\n\n`;
            commentBody += `- **Artifact Name:** \`preview-site\`\n`;
            commentBody += `- **Retention:** 30 days\n\n`;
            commentBody += `To download and view locally:\n\n`;
            commentBody += '```bash\n';
            commentBody += `curl -L -o preview-site.zip \\\n`;
            commentBody += `  "https://api.github.com/repos/${{ github.repository }}/actions/artifacts/${{ steps.upload_artifact.outputs.artifact_id }}/zip"\n`;
            commentBody += `unzip preview-site.zip\n`;
            commentBody += '```\n\n';

            if (previewGuideContent) {
              commentBody += `### 📖 Setup Guide\n\n`;
              commentBody += `${previewGuideContent}\n\n`;
            }

            commentBody += `> This preview will be automatically removed when the PR is closed.\n`;

            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            const previewComment = comments.find(comment => 
              comment.body.includes('## 🚀 Preview Deployment')
            );

            if (previewComment) {
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: previewComment.id,
                body: commentBody
              });
            } else {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: commentBody
              });
            }
